diff --git a/lib/mprintf.c b/lib/mprintf.c
index abe0df4..f39efb0 100644
--- a/lib/mprintf.c
+++ b/lib/mprintf.c
@@ -988,7 +988,7 @@ static bool out_string(void *userp,
       len = 0;
     }
   }
-  else if(prec != -1)
+  else if(prec >= 0)
     len = (size_t)prec;
   else if(*str == '\0')
     len = 0;
@@ -1009,7 +1009,7 @@ static bool out_string(void *userp,
   /* With no precision, len is already the exact length; emit it without
      scanning again. With precision, scan up to len but stop at NUL, since
      the string may be shorter or the buffer may not be NUL-terminated. */
-  if(prec == -1) {
+  if(prec < 0) {
     if(stream_run(userp, stream, streamn,
                   (const unsigned char *)str, len, donep))
       return TRUE;

diff --git a/lib/mprintf.c b/lib/mprintf.c
index ab1fa0b..a68308c 100644
--- a/lib/mprintf.c
+++ b/lib/mprintf.c
@@ -993,7 +993,7 @@ static bool out_string(void *userp,
       len = 0;
     }
   }
-  else if(prec >= 0)
+  else if(prec != -1)
     len = (size_t)prec;
   else if(*str == '\0')
     len = 0;
